pus-raspberry-pi-5-002", "model_id": "raspberry-pi-5", "serial_number": "DEMO-CAMPUS-RASPBERRY-PI-5-002", "status": "MAINTENANCE"}, {"unit_id": "campus-microbit-v2-001", "model_id": "microbit-v2", "serial_number": "DEMO-CAMPUS-MICROBIT-V2-001", "status": "AVAILABLE"}, {"unit_id": "campus-microbit-v2-002", "model_id": "microbit-v2", "serial_number": "DEMO-CAMPUS-MICROBIT-V2-002", "status": "AVAILABLE"}, {"unit_id": "campus-ti-84-plus-ce-001", "model_id": "ti-84-plus-ce", "serial_number": "DEMO-CAMPUS-TI-84-PLUS-CE-001", "status": "AVAILABLE"}, {"unit_id": "campus-ti-84-plus-ce-002", "model_id": "ti-84-plus-ce", "serial_number": "DEMO-CAMPUS-TI-84-PLUS-CE-002", "status": "AVAILABLE"}, {"unit_id": "campus-fluke-115-001", "model_id": "fluke-115", "serial_number": "DEMO-CAMPUS-FLUKE-115-001", "status": "AVAILABLE"}, {"unit_id": "campus-fluke-115-002", "model_id": "fluke-115", "serial_number": "DEMO-CAMPUS-FLUKE-115-002", "status": "AVAILABLE"}, {"unit_id": "campus-celestron-microscope-001", "model_id": "celestron-microscope", "serial_number": "DEMO-CAMPUS-CELESTRON-MICROSCOPE-001", "status": "AVAILABLE"}, {"unit_id": "campus-celestron-microscope-002", "model_id": "celestron-microscope", "serial_number": "DEMO-CAMPUS-CELESTRON-MICROSCOPE-002", "status": "AVAILABLE"}]';
    conflict_id TEXT;
BEGIN
    WITH campus_seed_models AS (SELECT * FROM jsonb_to_recordset(seed_models) AS m(id TEXT, name TEXT, category TEXT, description TEXT, image_url TEXT, image_alt TEXT, specifications JSONB, original_description TEXT)), campus_seed_units AS (SELECT * FROM jsonb_to_recordset(seed_units) AS u(unit_id TEXT, model_id TEXT, serial_number TEXT, status TEXT)),
    new_models AS (
        INSERT INTO loan.device_models (id, name, category, description, loan_duration_days,
            total_units, available_units, image_url, image_alt, specifications, updated_at)
        SELECT m.id, m.name, m.category, m.description, 14,
            (SELECT count(*) FROM campus_seed_units u WHERE u.model_id = m.id),
            (SELECT count(*) FROM campus_seed_units u WHERE u.model_id = m.id AND u.status = 'AVAILABLE'),
            m.image_url, m.image_alt, m.specifications, NOW()
        FROM campus_seed_models m
        ON CONFLICT (id) DO NOTHING RETURNING id
    )
    INSERT INTO loan.device_units (unit_id, model_id, serial_number, status, updated_at)
    SELECT u.unit_id, u.model_id, u.serial_number, u.status, NOW()
    FROM campus_seed_units u JOIN new_models m ON m.id = u.model_id;

    WITH campus_seed_models AS (SELECT * FROM jsonb_to_recordset(seed_models) AS m(id TEXT, name TEXT, category TEXT, description TEXT, image_url TEXT, image_alt TEXT, specifications JSONB, original_description TEXT))
    UPDATE loan.device_models d SET
        description = m.description,
        image_url = COALESCE(d.image_url, m.image_url),
        image_alt = COALESCE(d.image_alt, m.image_alt),
        specifications = CASE WHEN d.specifications = '[]'::jsonb THEN m.specifications ELSE d.specifications END,
        updated_at = NOW()
    FROM campus_seed_models m WHERE d.id = m.id
        AND d.description IN (m.original_description, m.description)
        AND (d.description <> m.description OR d.image_url IS NULL OR d.image_alt IS NULL OR d.specifications = '[]'::jsonb);

    FOR conflict_id IN
        WITH campus_seed_models AS (SELECT * FROM jsonb_to_recordset(seed_models) AS m(id TEXT, name TEXT, category TEXT, description TEXT, image_url TEXT, image_alt TEXT, specifications JSONB, original_description TEXT))
        SELECT d.id FROM loan.device_models d JOIN campus_seed_models m ON m.id = d.id
        WHERE d.description NOT IN (m.original_description, m.description)
    LOOP
        RAISE WARNING 'Catalogue seed preserved edited description and metadata for %; review specs manually', conflict_id;
    END LOOP;
END $campus$;
